-- Phase 3 workflow hardening: assessment review/approval/publish, missing-score counts,
-- assignment-aware score reads, and complete report-card subject aggregation.
create or replace function public.advance_assessment_status(p_assessment_id uuid,p_status text) returns public.assessments language plpgsql security definer set search_path=public as $$ declare a public.assessments; begin select * into a from public.assessments where id=p_assessment_id and school_id=current_school_id() for update; if not found then raise exception 'Assessment not found'; end if; if p_status not in('review','approved','published') then raise exception 'Invalid status'; end if; if p_status='review' then if not(is_school_manager() or teacher_has_assignment(a.class_id,a.subject_id)) then raise exception 'Not assigned to this assessment'; end if; if a.workflow_status not in('draft','review') then raise exception 'Assessment cannot move to review'; end if; elsif p_status in('approved','published') then if not is_school_manager() then raise exception 'Manager permission required'; end if; if p_status='approved' and a.workflow_status<>'review' then raise exception 'Assessment must be reviewed first'; end if; if p_status='published' and a.workflow_status<>'approved' then raise exception 'Assessment must be approved first'; end if; end if; update public.assessments set workflow_status=p_status,published=(p_status='published'),updated_at=now() where id=a.id returning * into a; return a; end; $$;
revoke all on function public.advance_assessment_status(uuid,text) from public,anon; grant execute on function public.advance_assessment_status(uuid,text) to authenticated;
drop policy if exists assessment_scores_select on public.assessment_scores; create policy assessment_scores_select on public.assessment_scores for select using(school_id=current_school_id() and exists(select 1 from public.assessments a where a.id=assessment_id and(is_school_manager() or teacher_has_assignment(a.class_id,a.subject_id))));
create or replace function public.assessment_missing_counts(p_assessment_id uuid) returns table(total_students bigint,scored_students bigint,missing_students bigint) language sql security definer stable set search_path=public as $$ select count(*)::bigint,count(sc.id)::bigint,(count(*)-count(sc.id))::bigint from public.assessments a join public.students s on s.school_id=a.school_id and s.class_id=a.class_id and not s.is_archived left join public.assessment_scores sc on sc.assessment_id=a.id and sc.student_id=s.id where a.id=p_assessment_id and a.school_id=current_school_id() and(is_school_manager() or teacher_has_assignment(a.class_id,a.subject_id)); $$;
revoke all on function public.assessment_missing_counts(uuid) from public,anon; grant execute on function public.assessment_missing_counts(uuid) to authenticated;
create or replace function public.generate_term_report_cards(p_session_id uuid,p_term_id uuid) returns integer language plpgsql security definer set search_path=public as $$ declare r record;n integer:=0;tot numeric;mx numeric;avg numeric;pos integer;rcid uuid;subj record;ctot numeric;cmx numeric;etot numeric;emx numeric;begin if not is_school_manager() then raise exception 'Manager permission required';end if; for r in select id,class_id from public.students where school_id=current_school_id() and not is_archived loop select coalesce(sum(sc.score),0),coalesce(sum(a.max_score),0) into tot,mx from public.assessment_scores sc join public.assessments a on a.id=sc.assessment_id where sc.student_id=r.id and a.school_id=current_school_id() and a.session_id=p_session_id and a.term_id=p_term_id and a.workflow_status in('approved','published'); avg=case when mx>0 then round(tot/mx*100,2) else 0 end; insert into public.report_cards(school_id,student_id,session_id,term_id,class_id,total_score,average_score,status) values(current_school_id(),r.id,p_session_id,p_term_id,r.class_id,tot,avg,'draft') on conflict(student_id,session_id,term_id) do update set class_id=excluded.class_id,total_score=excluded.total_score,average_score=excluded.average_score,status='draft',published_at=null,updated_at=now() returning id into rcid; delete from public.report_card_subjects where report_card_id=rcid; for subj in select distinct a.subject_id from public.assessments a where a.school_id=current_school_id() and a.session_id=p_session_id and a.term_id=p_term_id and a.class_id=r.class_id loop select coalesce(sum(sc.score) filter(where lower(a.assessment_type)='ca'),0),coalesce(sum(a.max_score) filter(where lower(a.assessment_type)='ca'),0),coalesce(sum(sc.score) filter(where lower(a.assessment_type)='exam'),0),coalesce(sum(a.max_score) filter(where lower(a.assessment_type)='exam'),0) into ctot,cmx,etot,emx from public.assessments a left join public.assessment_scores sc on sc.assessment_id=a.id and sc.student_id=r.id where a.school_id=current_school_id() and a.session_id=p_session_id and a.term_id=p_term_id and a.class_id=r.class_id and a.subject_id=subj.subject_id and a.workflow_status in('approved','published'); insert into public.report_card_subjects(school_id,report_card_id,subject_id,ca_score,exam_score,total_score,grade) values(current_school_id(),rcid,subj.subject_id,ctot,etot,ctot+etot,public.grade_for_percentage(current_school_id(),case when cmx+emx>0 then (ctot+etot)/(cmx+emx)*100 else 0 end)); end loop;n=n+1;end loop;for r in select id,class_id,average_score from public.report_cards where school_id=current_school_id() and session_id=p_session_id and term_id=p_term_id loop select 1+count(*) into pos from public.report_cards x where x.school_id=current_school_id() and x.session_id=p_session_id and x.term_id=p_term_id and x.class_id=r.class_id and x.average_score>r.average_score;update public.report_cards set position=pos where id=r.id;end loop;return n;end; $$;
revoke all on function public.generate_term_report_cards(uuid,uuid) from public,anon; grant execute on function public.generate_term_report_cards(uuid,uuid) to authenticated;
